using System;using System.Collections.Generic;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class ProductionView:MonoBehaviour {
  GameRuntime game;float next;readonly bool[] expanded=new bool[4];readonly Button[] headings=new Button[4];readonly Text[] facts=new Text[4];Text hardware;Button hardwareToggle;bool hardwareOpen;
  public void Initialize(GameRuntime runtime){game=runtime;bool de=game.State.Settings.language=="de";WorkshopUIFactory.Label("ProductionTitle",transform,de?"Produktion":"Production",18,44);WorkshopUIFactory.Label("ProductionHint",transform,de?"Kennzahl antippen, um ihre Quellen zu sehen.":"Tap a metric to see its sources.",13,40).color=GameTheme.Muted;
   for(int i=0;i<4;i++){int index=i;headings[i]=WorkshopUIFactory.Button("ProductionSources-"+new[]{"compute","users","credits","data"}[i],transform,"",()=>{expanded[index]=!expanded[index];Refresh();});facts[i]=WorkshopUIFactory.Label(i==0?"ProductionFacts":"ProductionFacts-"+i,transform,"",13,24);facts[i].alignment=TextAnchor.UpperLeft;facts[i].GetComponent<LayoutElement>().preferredHeight=-1;}
   hardwareToggle=WorkshopUIFactory.Button("ProductionHardware",transform,"",()=>{hardwareOpen=!hardwareOpen;Refresh();});hardware=WorkshopUIFactory.Label("ProductionHardwareFacts",transform,"",13,24);hardware.GetComponent<LayoutElement>().preferredHeight=-1;Refresh();
  }
  void Update(){if(Time.unscaledTime>=next){next=Time.unscaledTime+.5f;Refresh();}}
  static string Friendly(string id,string language){if(id=="Challenge no-items")return UiLocalizedText.Translate("Challenge ohne Items",language);string value=System.Text.RegularExpressions.Regex.Replace(id,@"\b[HTFIDO]\d{2}\b",m=>{var node=Array.Find(PrestigeBalance.Nodes,n=>n.Id==m.Value);return node==null?m.Value:node.Name;});return UiLocalizedText.Translate(value,language);}
  void Refresh(){string N(ScientificNumber n)=>NumberFormatting.Format(n,game.State.Settings.numberFormat,game.State.Settings.language);var s=game.State;bool de=s.Settings.language=="de";var labels=new[]{"Compute",de?"Nutzer":"Users","Credits/s",de?"Daten/s":"Data/s"};
   for(int i=0;i<4;i++){var steps=new List<ProductionStep>();var result=i==0?Game.ComputeTrace(s,steps):i==1?Game.UsersTrace(s,steps):i==2?Game.IncomeTrace(s,steps):Game.DataRateTrace(s,steps);headings[i].GetComponentInChildren<Text>().text=labels[i]+" · "+N(result)+(expanded[i]?"  −":"  +");facts[i].gameObject.SetActive(expanded[i]);if(expanded[i]){var lines=new List<string>();foreach(var step in steps)lines.Add(Friendly(step.Id,s.Settings.language)+": ×"+N(step.Factor)+" → "+N(step.After));facts[i].text=string.Join("\n",lines);}}
   var owned=new List<string>();for(int i=0;i<s.Hardware.Length;i++)if(s.Hardware[i]>0)owned.Add(SettingsRules.Text(s.Settings.language,"hardware:"+Balance.Hardware[i].Id)+" ×"+s.Hardware[i]+(Array.IndexOf(s.Legacy.classUpgrades,Balance.Hardware[i].Id)>=0?" · Legacy class upgrade ×"+CompatibilityCatalog.ClassUpgradeMultiplier:""));hardwareToggle.GetComponentInChildren<Text>().text="Hardware · "+owned.Count+(hardwareOpen?"  −":"  +");hardware.gameObject.SetActive(hardwareOpen);hardware.text=string.Join("\n",owned);
  }
 }
}
